mapper.select:
SELECT *
FROM message
WHERE user_id = #{userId}
  AND deleted = false
ORDER BY id DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE message
SET is_read = true
WHERE id = #{id}
  AND user_id = #{userId}

UPDATE message
SET deleted = true
WHERE id = #{id}
  AND user_id = #{userId}
